    .hero-content { width: min(100%, 900px); }
    h1 { max-width: 760px; margin: 0 0 28px; font-family: Georgia, '"'Times New Roman', serif; font-size: clamp(76px, 10.8vw, 166px); font-weight: 400; line-height: .95; letter-spacing: -.055em; text-wrap: balance; }
    .intro { margin: 0; font-size: clamp(16px, 1.4vw, 20px); line-height: 1.6; letter-spacing: .015em; }
