      position: absolute;
      bottom: 28px;
      left: var(--gutter);
      right: var(--gutter);
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 20px;
      padding-top: 16px;
      border-top: 1px solid rgba(244, 241, 232, .35);
      font-size: 11px;
      line-height: 1.6;
      letter-spacing: .12em;
      text-transform: uppercase;
    }
    .caption-rule { width: 36px; height: 1px; background: currentColor; opacity: .7; }
    .work { padding: 72px var(--gutter) 88px; display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: start; scroll-margin-top: 24px; }
    h2 { margin: 0; font-family: Georgia, 'Times New Roman', serif; font-size: clamp(40px, 4.5vw, 68px); font-weight: 400; line-height: 1.1; letter-spacing: -.04em; }
